<script>
function am54FilterPartSelect(input){
  const select=input.closest('form')?.querySelector('select[name="part_master_id"]');
  if(!select)return;
  const q=(input.value||'').toLocaleLowerCase().trim();
  for(const opt of select.options){
    opt.hidden=!!q && !!opt.value && !opt.text.toLocaleLowerCase().includes(q);
  }
  if(q && select.selectedOptions[0]?.hidden)select.value='';
}
</script>
