private function syncJobTotals(int $jobId): void
{
    // FIX54_SIMPLE_PARTS: Estimate->Job Card release must preserve GST-inclusive totals.
    // All released Part lines remain editable PLANNED lines until Close.
    $parts=JobCardPart::query()->where('job_card_id',$jobId)->orderBy('id')->get();
    $labour=JobCardLabour::query()->where('job_card_id',$jobId)->orderBy('id')->get();
    $tax=\App\Services\JobCardTaxTotals::forJob($jobId);
    JobCard::query()->whereKey($jobId)->update([
        'parts_json'=>json_encode($parts->toArray(),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),
        'labour_json'=>json_encode($labour->toArray(),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES),
        'parts_total'=>$tax['parts_total'],'labour_total'=>$tax['labour_total'],
        'gst_total'=>$tax['gst_total'],'pre_round_total'=>$tax['pre_round_total'],
        'round_off'=>$tax['round_off'],'grand_total'=>$tax['grand_total'],
    ]);
}
